package marked

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

// referenceCase is one case of the token reference.
type referenceCase struct {
	Name     string         `json:"name"`
	Markdown string         `json:"markdown"`
	Options  map[string]any `json:"options"`
	Tokens   []any          `json:"tokens"`
}

// TestTokenParityWithMarked compares the port against the token stream that
// marked 18.0.11 produces for marked's own test corpus.
//
// The reference is generated by scripts/marked-token-reference.mjs.
func TestTokenParityWithMarked(t *testing.T) {
	cases := loadReferenceCases(t)

	for _, testCase := range cases {
		testCase := testCase
		t.Run(testCase.Name, func(t *testing.T) {
			options := referenceOptions(testCase)
			tokens, _ := Lex(testCase.Markdown, options)

			got := canonicalTokens(tokens)
			want := testCase.Tokens

			if normalizeJSON(got) != normalizeJSON(want) {
				t.Fatalf("token stream differs for %q\nmarkdown: %q\ngot:  %s\nwant: %s",
					testCase.Name, testCase.Markdown, compactJSON(got), compactJSON(want))
			}
		})
	}
}

// referenceOptions returns the options that marked's spec runner uses for a
// case. The reference holds the options of every case, because marked's own
// corpus overrides them per file.
func referenceOptions(testCase referenceCase) *MarkedOptions {
	options := DefaultOptions()
	for key, value := range testCase.Options {
		switch key {
		case "gfm":
			options.GFM = value == true
		case "pedantic":
			options.Pedantic = value == true
		case "breaks":
			options.Breaks = value == true
		case "silent":
			options.Silent = value == true
		}
	}
	return options
}

// loadReferenceCases reads the token reference.
func loadReferenceCases(t *testing.T) []referenceCase {
	t.Helper()
	path := filepath.Join("testdata", "tokens.json")
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read reference: %v", err)
	}
	var cases []referenceCase
	if err := json.Unmarshal(data, &cases); err != nil {
		t.Fatalf("parse reference: %v", err)
	}
	if len(cases) == 0 {
		t.Fatal("reference is empty")
	}
	return cases
}

// canonicalTokens renders a token stream the way the reference script does.
func canonicalTokens(tokens []Token) []any {
	out := make([]any, 0, len(tokens))
	for i := range tokens {
		out = append(out, canonicalToken(&tokens[i]))
	}
	return out
}

// canonicalToken renders one token the way the reference script does.
func canonicalToken(token *Token) map[string]any {
	out := map[string]any{
		"type": token.Type,
		"raw":  token.Raw,
	}
	switch token.Type {
	case TypeCode:
		out["text"] = token.Text
		out["lang"] = token.Lang
		out["codeBlockStyle"] = token.CodeBlockStyle
	case TypeHeading:
		out["text"] = token.Text
		out["depth"] = token.Depth
		out["tokens"] = canonicalTokens(token.Tokens)
	case TypeBlockquote:
		out["text"] = token.Text
		out["tokens"] = canonicalTokens(token.Tokens)
	case TypeList:
		out["ordered"] = token.Ordered
		if token.HasStart {
			out["start"] = token.Start
		} else {
			out["start"] = ""
		}
		out["loose"] = token.Loose
		items := make([]any, 0, len(token.Items))
		for i := range token.Items {
			items = append(items, map[string]any{
				"raw":     token.Items[i].Raw,
				"task":    token.Items[i].Task,
				"checked": token.Items[i].Checked,
				"loose":   token.Items[i].Loose,
				"text":    token.Items[i].Text,
				"tokens":  canonicalTokens(token.Items[i].Tokens),
			})
		}
		out["items"] = items
	case TypeHTML:
		out["text"] = token.Text
		out["block"] = token.Block
		out["inLink"] = token.InLink
		out["inRawBlock"] = token.InRawBlock
		// marked's inline html has no pre flag.
		if token.Block {
			out["pre"] = token.Pre
		}
	case TypeDef:
		out["tag"] = token.Tag
		out["href"] = token.Href
		out["title"] = derefString(token.Title)
	case TypeTable:
		align := make([]any, 0, len(token.Align))
		for _, value := range token.Align {
			if value == "" {
				align = append(align, nil)
				continue
			}
			align = append(align, value)
		}
		out["align"] = align
		out["header"] = canonicalCells(token.Header)
		rows := make([]any, 0, len(token.Rows))
		for _, row := range token.Rows {
			rows = append(rows, canonicalCells(row))
		}
		out["rows"] = rows
	case TypeParagraph, TypeText:
		out["text"] = token.Text
		out["tokens"] = canonicalTokens(token.Tokens)
	case TypeEscape:
		out["text"] = token.Text
	case TypeLink, TypeImage:
		out["text"] = token.Text
		out["href"] = token.Href
		out["title"] = derefString(token.Title)
		out["tokens"] = canonicalTokens(token.Tokens)
	case TypeStrong, TypeEm, TypeDel:
		out["text"] = token.Text
		out["tokens"] = canonicalTokens(token.Tokens)
	case TypeCodespan:
		out["text"] = token.Text
	case TypeCheckbox:
		out["checked"] = token.Checked
	}
	return out
}

// canonicalCells renders the cells of a table row.
func canonicalCells(cells []TableCell) []any {
	out := make([]any, 0, len(cells))
	for _, cell := range cells {
		align := any(nil)
		if cell.Align != "" {
			align = cell.Align
		}
		out = append(out, map[string]any{
			"text":   cell.Text,
			"header": cell.Header,
			"align":  align,
			"tokens": canonicalTokens(cell.Tokens),
		})
	}
	return out
}

// normalizeJSON renders a value as JSON with sorted keys, so that the numbers
// of the reference and of the port compare equal.
func normalizeJSON(value any) string {
	data, err := json.Marshal(value)
	if err != nil {
		return err.Error()
	}
	var decoded any
	if err := json.Unmarshal(data, &decoded); err != nil {
		return string(data)
	}
	normalized, err := json.Marshal(decoded)
	if err != nil {
		return string(data)
	}
	return string(normalized)
}

// compactJSON renders a value as compact JSON.
func compactJSON(value any) string {
	data, err := json.Marshal(value)
	if err != nil {
		return err.Error()
	}
	return string(data)
}
